def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = 0
    for x in op:
        if x == 'C':
            opp_c += 1
    opp_d = n - opp_c

    last_me = me[-1]
    last_opp = op[-1]

    r10 = op[-10:]
    r20 = op[-20:]

    recent10_d = 0
    for x in r10:
        if x == 'D':
            recent10_d += 1

    recent20_d = 0
    for x in r20:
        if x == 'D':
            recent20_d += 1

    recent10_c = len(r10) - recent10_d
    recent20_c = len(r20) - recent20_d

    streak_d = 0
    for x in reversed(op):
        if x == 'D':
            streak_d += 1
        else:
            break

    if opp_c * 100 < n * 30 or recent10_d >= 9 or streak_d >= 8:
        return 'D'

    if recent10_d >= 8:
        return 'D'

    ft = 0
    pt = 0
    fr = 0
    pr = 0
    start = n - 20
    if start < 1:
        start = 1

    for i in range(1, n):
        if me[i - 1] == 'D':
            if op[i] == 'C':
                ft += 1
                if i >= start:
                    fr += 1
            else:
                pt += 1
                if i >= start:
                    pr += 1

    high_coop = opp_c * 100 >= n * 65
    med_coop = opp_c * 100 >= n * 55
    very_coop = opp_c * 100 >= n * 80

    exploitable = False

    if opp_c == n and n >= 12:
        exploitable = True
    elif recent10_c >= 8 and recent20_c >= 12 and pr == 0 and fr >= 1:
        exploitable = True
    elif recent10_c >= 7 and fr >= 3 and pr <= 1 and med_coop:
        exploitable = True
    elif recent10_c >= 8 and ft >= 3 and pt == 0 and recent20_c >= 10:
        exploitable = True
    elif recent10_c >= 9 and recent20_c >= 15 and high_coop and pr == 0 and pt <= 1:
        exploitable = True

    if exploitable:
        return 'D'

    if last_opp == 'D':
        if last_me == 'D':
            if high_coop and recent20_c >= 6 and streak_d <= 6:
                return 'C'
            if med_coop and recent20_c >= 8 and streak_d <= 4:
                return 'C'
            return 'D'
        else:
            if streak_d == 1 and high_coop and recent10_d <= 2:
                return 'C'
            if streak_d == 1 and med_coop and recent10_d <= 1 and recent20_c >= 8:
                return 'C'
            if streak_d <= 2 and very_coop and recent10_d <= 4 and opp_d <= 3:
                return 'C'
            return 'D'

    if last_opp == 'C':
        if last_me == 'D':
            if n >= 97 and very_coop and recent10_c >= 9:
                return 'D'
            return 'C'

        if n >= 25 and very_coop and recent10_c >= 9 and pt <= 1 and pr == 0:
            if rng.random() < 0.12:
                return 'D'
        return 'C'

    return 'C'
